@startuml

class City {
  + Name : string
  + Inhabitants : int
}

class Attraction {
  + Name : string
  + Address : string
}

class GuidedTour {
  + Duration : int
  + Number : int
}

class Discount {
  + Amount : double
}

abstract class Person {
  + Name : string
}

class Visitor extends Person {}

class Guide extends Person {}

City "1" -- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "*" -- "1" Guide
GuidedTour "0..*" -- "1..20" Visitor
Visitor "0..*" -- "0..*" GuidedTour : Discount
Discount "*" -- "1" Visitor
Discount "*" -- "1" GuidedTour

@enduml

